function raidJournalKey(){return ACC&&typeof ACC.id==='string'&&ACC.id&&ACC.token?'ew_raid_pending_v1_'+encodeURIComponent(ACC.id):null;}
function raidJournalRead(){const key=raidJournalKey();if(!key)return null;try{
